package com.atlasiq.security;
import com.atlasiq.qir.Finding;import jakarta.enterprise.context.ApplicationScoped;import java.nio.file.*;import java.util.*;import java.util.stream.Stream;
@ApplicationScoped public class IacSecurityScanner {public List<Finding> scan(Path root){List<Finding> out=new ArrayList<>();try(Stream<Path>s=Files.walk(root,8)){s.filter(Files::isRegularFile).forEach(p->{try{String x=Files.readString(p);String f=root.relativize(p).toString();if(f.endsWith(".tf")&&x.contains("0.0.0.0/0"))out.add(new Finding("security","high","Public network exposure in Terraform",f,"iac:"+f));if((f.endsWith(".yaml")||f.endsWith(".yml"))&&x.contains("privileged: true"))out.add(new Finding("security","critical","Privileged Kubernetes container",f,"iac:"+f));if((f.endsWith(".yaml")||f.endsWith(".yml"))&&x.contains("runAsUser: 0"))out.add(new Finding("security","high","Kubernetes workload runs as root",f,"iac:"+f));}catch(Exception ignored){}});}catch(Exception ignored){}return List.copyOf(out);}}
